namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);
        if (tier == CustomerTier.Blocked)
            return 0m;

        var adjusted = ApplyTierAdjustment(subtotal, tier);
        adjusted = ApplyDiscounts(adjusted, subtotal, order.DiscountOverride);
        adjusted = ApplyChannelAdjustment(adjusted, order.Channel);
        return Math.Max(0m, adjusted);
    }

    private static decimal CalculateSubtotal(Order order) =>
        order.Lines.Sum(line => line.UnitPrice * line.Quantity);

    private static decimal ApplyTierAdjustment(decimal amount, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? amount * 0.95m : amount;

    private static decimal ApplyDiscounts(decimal amount, decimal subtotal, decimal? discountOverride)
    {
        if (discountOverride is > 0m)
            amount -= discountOverride.Value;
        if (subtotal > 500m)
            amount -= 10m;
        return amount;
    }

    private static decimal ApplyChannelAdjustment(decimal amount, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Phone => amount + 2m,
            OrderChannel.Marketplace => amount * 1.02m,
            _ => amount
        };
}
